import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  interpolate,
  Img,
  staticFile,
} from "remotion";
import { TransitionSeries, linearTiming } from "@remotion/transitions";
import { fade } from "@remotion/transitions/fade";
import { BRAND } from "@/lib/brand";
import {
  SPRINGS,
  TIMING,
  springIn,
  staggeredSpring,
  ambientDrift,
} from "../motion";

export const fps = 25;

const COLORS = {
  bg: BRAND.colors.bg,
  card: BRAND.colors.card,
  border: BRAND.colors.border,
  text: BRAND.colors.text,
  textMuted: BRAND.colors.textMuted,
  textSubtle: BRAND.colors.textSubtle,
  orange: BRAND.colors.orange,
  orangeDeep: BRAND.colors.orangeDeep,
  orangeTint: BRAND.colors.orangeTint,
};

const TRANSITION = 15;
const SCENE_ONE = 100;
const SCENE_TWO = 250;

export const durationInFrames =
  20 + TRANSITION + SCENE_ONE + TRANSITION + SCENE_TWO + TRANSITION + 25;

// ============================================================
// Background — flat Apify canvas
// ============================================================
const Background: React.FC = () => (
  <AbsoluteFill style={{ backgroundColor: COLORS.bg }} />
);

const BlackScreen: React.FC = () => (
  <AbsoluteFill style={{ backgroundColor: COLORS.bg }} />
);

// ============================================================
// Crosshair "+" decoration
// ============================================================
const Crosshair: React.FC<{
  x: number;
  y: number;
  size: number;
  opacity: number;
  rotate?: number;
}> = ({ x, y, size, opacity, rotate = 0 }) => {
  const stroke = Math.max(2, size * 0.08);
  return (
    <svg
      style={{
        position: "absolute",
        left: `${x * 100}%`,
        top: `${y * 100}%`,
        width: size,
        height: size,
        transform: `translate(-50%, -50%) rotate(${rotate}deg)`,
        opacity,
      }}
      viewBox="0 0 24 24"
    >
      <line
        x1="12"
        y1="2"
        x2="12"
        y2="22"
        stroke={COLORS.orange}
        strokeWidth={stroke}
        strokeLinecap="round"
      />
      <line
        x1="2"
        y1="12"
        x2="22"
        y2="12"
        stroke={COLORS.orange}
        strokeWidth={stroke}
        strokeLinecap="round"
      />
    </svg>
  );
};

// ============================================================
// Apify wordmark (top-left header)
// ============================================================
const Wordmark: React.FC<{ delay?: number }> = ({ delay = 0 }) => {
  const frame = useCurrentFrame();
  const { fps: vfps } = useVideoConfig();
  const headerIn = springIn(frame, vfps, delay, "GENTLE");
  const driftY = ambientDrift(frame, 1.5, 140, "wordmark");

  return (
    <div
      style={{
        position: "absolute",
        left: 220,
        top: 200,
        opacity: headerIn,
        transform: `translateY(${
          interpolate(headerIn, [0, 1], [-12, 0]) + driftY
        }px)`,
        display: "flex",
        alignItems: "center",
        gap: 24,
        fontFamily: "Inter, sans-serif",
      }}
    >
      <Img
        src={staticFile("assets/apify/Apify symbol colors.svg")}
        style={{ height: 88, width: "auto" }}
      />
      <Img
        src={staticFile("assets/apify/Apify Logo white Wordmark.svg")}
        style={{ height: 70, width: "auto" }}
      />
    </div>
  );
};

// ============================================================
// SCENE 1 — Credits headline reveal
// "Start your free trial. Get $5 in free credits."
// ============================================================
const SceneOne: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: vfps, width, height } = useVideoConfig();

  const leadIn = springIn(frame, vfps, 6, "SNAPPY");
  const dollarIn = springIn(frame, vfps, 22, "LIQUID");
  const tailIn = springIn(frame, vfps, 40, "GENTLE");
  const subIn = springIn(frame, vfps, 56, "GENTLE");
  const decoIn = springIn(frame, vfps, 30, "GENTLE");

  // Animated dollar count-up: 0 -> 5
  const countProgress = springIn(frame, vfps, 22, "LIQUID");
  const dollarValue = Math.round(interpolate(countProgress, [0, 1], [0, 5]));

  const headlineDriftY = ambientDrift(frame, 3, 110, "headline-1");
  const subDriftY = ambientDrift(frame, 2, 130, "sub-1");

  // Pill mask reveal
  const pillReveal = interpolate(dollarIn, [0, 1], [100, 0]);

  return (
    <AbsoluteFill style={{ fontFamily: "Inter, sans-serif" }}>
      <Background />

      {/* Decorative crosshairs scattered around */}
      <Crosshair x={0.08} y={0.16} size={48} opacity={decoIn * 0.55} />
      <Crosshair x={0.93} y={0.22} size={42} opacity={decoIn * 0.5} />
      <Crosshair x={0.12} y={0.84} size={44} opacity={decoIn * 0.45} />
      <Crosshair x={0.91} y={0.81} size={48} opacity={decoIn * 0.55} />
      <Crosshair x={0.5} y={0.92} size={36} opacity={decoIn * 0.35} />

      <Wordmark delay={0} />

      {/* Headline column — anchored slightly left of center */}
      <div
        style={{
          position: "absolute",
          left: "10%",
          top: "32%",
          width: "80%",
          fontFamily: "'GT Walsheim', Inter, sans-serif",
          transform: `translateY(${headlineDriftY}px)`,
        }}
      >
        {/* Line 1 */}
        <div
          style={{
            fontFamily: "'GT Walsheim', Inter, sans-serif",
            fontWeight: 700,
            fontSize: 220,
            color: COLORS.text,
            letterSpacing: "-0.035em",
            lineHeight: 1.02,
            opacity: leadIn,
            transform: `translateY(${interpolate(leadIn, [0, 1], [40, 0])}px)`,
          }}
        >
          Start your free trial.
        </div>

        {/* Line 2 — with highlighted $5 phrase */}
        <div
          style={{
            fontFamily: "'GT Walsheim', Inter, sans-serif",
            fontWeight: 700,
            fontSize: 220,
            color: COLORS.text,
            letterSpacing: "-0.035em",
            lineHeight: 1.02,
            marginTop: 32,
            opacity: tailIn,
            transform: `translateY(${interpolate(tailIn, [0, 1], [28, 0])}px)`,
          }}
        >
          Get{" "}
          <span
            style={{
              fontFamily: "'GT Walsheim', Inter, sans-serif",
              background: COLORS.orangeTint,
              borderBottom: `8px solid ${COLORS.orange}`,
              padding: "0 28px",
              borderRadius: 18,
              clipPath: `inset(0 ${pillReveal}% 0 0)`,
              fontVariantNumeric: "tabular-nums",
            }}
          >
            ${dollarValue} in free credits
          </span>
          .
        </div>
      </div>

      {/* Subhead */}
      <div
        style={{
          position: "absolute",
          left: "10%",
          top: "70%",
          width: "70%",
          fontFamily: "Inter, sans-serif",
          fontWeight: 500,
          fontSize: 56,
          color: COLORS.textMuted,
          letterSpacing: "-0.005em",
          lineHeight: 1.3,
          opacity: subIn,
          transform: `translateY(${
            interpolate(subIn, [0, 1], [16, 0]) + subDriftY
          }px)`,
        }}
      >
        Enough to run your first price scrape today — no card required.
      </div>
    </AbsoluteFill>
  );
};

// ============================================================
// SCENE 2 — End card with CTA, checklist, promo line
// ============================================================
const ITEMS = [
  "Run your first Actor in minutes",
  "$5 in free credits, no card required",
  "25,000+ ready-made scrapers",
];

const CheckIcon: React.FC<{ size: number; progress: number }> = ({
  size,
  progress,
}) => (
  <svg
    width={size}
    height={size}
    viewBox="0 0 24 24"
    style={{ flexShrink: 0, opacity: progress }}
  >
    <path
      d="M5 12.5 L10 17.5 L19 7"
      stroke={COLORS.orange}
      strokeWidth={2.75}
      strokeLinecap="round"
      strokeLinejoin="round"
      fill="none"
      strokeDasharray={28}
      strokeDashoffset={interpolate(progress, [0, 1], [28, 0])}
    />
  </svg>
);

const SceneTwo: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: vfps, width, height } = useVideoConfig();

  const titleLeadIn = springIn(frame, vfps, 6, "SNAPPY");
  const titleHighlightIn = springIn(frame, vfps, 18, "LIQUID");
  const cardIn = springIn(frame, vfps, 30, "LIQUID");
  const ctaIn = springIn(frame, vfps, 95, "SNAPPY");
  const promoIn = springIn(frame, vfps, 110, "GENTLE");
  const decoIn = springIn(frame, vfps, 20, "GENTLE");

  // Ambient
  const titleDriftY = ambientDrift(frame, 2, 120, "title-2");
  const ctaBreathe = ambientDrift(frame, 1.5, 90, "cta-breathe");
  const ctaGlow = 0.5 + ambientDrift(frame, 0.15, 70, "cta-glow");

  // Pill mask
  const pillReveal = interpolate(titleHighlightIn, [0, 1], [100, 0]);

  return (
    <AbsoluteFill style={{ fontFamily: "Inter, sans-serif" }}>
      <Background />

      {/* Decorative crosshairs */}
      <Crosshair x={0.07} y={0.18} size={48} opacity={decoIn * 0.55} />
      <Crosshair x={0.94} y={0.24} size={42} opacity={decoIn * 0.5} />
      <Crosshair x={0.06} y={0.82} size={46} opacity={decoIn * 0.5} />
      <Crosshair x={0.95} y={0.86} size={44} opacity={decoIn * 0.55} />
      <Crosshair x={0.32} y={0.5} size={32} opacity={decoIn * 0.3} />
      <Crosshair x={0.68} y={0.5} size={32} opacity={decoIn * 0.3} />

      <Wordmark delay={0} />

      {/* Main column */}
      <div
        style={{
          position: "absolute",
          left: "8%",
          top: "20%",
          width: "84%",
          display: "flex",
          flexDirection: "column",
          alignItems: "flex-start",
          gap: 80,
        }}
      >
        {/* Headline */}
        <div
          style={{
            fontFamily: "'GT Walsheim', Inter, sans-serif",
            fontWeight: 700,
            fontSize: 180,
            color: COLORS.text,
            letterSpacing: "-0.03em",
            lineHeight: 1.04,
            transform: `translateY(${titleDriftY}px)`,
          }}
        >
          <div
            style={{
              fontFamily: "'GT Walsheim', Inter, sans-serif",
              opacity: titleLeadIn,
              transform: `translateY(${interpolate(
                titleLeadIn,
                [0, 1],
                [28, 0],
              )}px)`,
            }}
          >
            Scrape your first price
          </div>
          <div
            style={{
              fontFamily: "'GT Walsheim', Inter, sans-serif",
              opacity: titleLeadIn,
              transform: `translateY(${interpolate(
                titleLeadIn,
                [0, 1],
                [28, 0],
              )}px)`,
              marginTop: 20,
            }}
          >
            with{" "}
            <span
              style={{
                fontFamily: "'GT Walsheim', Inter, sans-serif",
                background: COLORS.orangeTint,
                borderBottom: `7px solid ${COLORS.orange}`,
                padding: "0 22px",
                borderRadius: 14,
                clipPath: `inset(0 ${pillReveal}% 0 0)`,
              }}
            >
              $5 free
            </span>{" "}
            today.
          </div>
        </div>

        {/* Card with bullets + CTA row */}
        <div
          style={{
            backgroundColor: COLORS.card,
            border: `1px solid ${COLORS.border}`,
            borderRadius: 32,
            padding: "64px 80px",
            width: "100%",
            display: "flex",
            flexDirection: "column",
            gap: 56,
            fontFamily: "Inter, sans-serif",
            opacity: cardIn,
            transform: `translateY(${interpolate(
              cardIn,
              [0, 1],
              [40, 0],
            )}px) scale(${interpolate(cardIn, [0, 1], [0.97, 1])})`,
            boxShadow: `0 24px 80px rgba(0,0,0,0.45)`,
          }}
        >
          {/* Bullet list */}
          <div
            style={{
              display: "flex",
              flexDirection: "column",
              gap: 36,
              fontFamily: "Inter, sans-serif",
            }}
          >
            {ITEMS.map((item, i) => {
              const itemIn = staggeredSpring(
                frame,
                vfps,
                i,
                40,
                TIMING.staggerItem,
                "GENTLE",
              );
              return (
                <div
                  key={i}
                  style={{
                    display: "flex",
                    alignItems: "center",
                    gap: 36,
                    opacity: itemIn,
                    transform: `translateX(${interpolate(
                      itemIn,
                      [0, 1],
                      [-32, 0],
                    )}px)`,
                    fontFamily: "Inter, sans-serif",
                  }}
                >
                  <CheckIcon size={56} progress={itemIn} />
                  <div
                    style={{
                      fontFamily: "Inter, sans-serif",
                      fontWeight: 600,
                      fontSize: 56,
                      color: COLORS.text,
                      letterSpacing: "-0.008em",
                      lineHeight: 1.2,
                    }}
                  >
                    {item}
                  </div>
                </div>
              );
            })}
          </div>

          {/* Divider */}
          <div
            style={{
              height: 1,
              backgroundColor: COLORS.border,
              width: "100%",
              opacity: cardIn,
            }}
          />

          {/* CTA Row */}
          <div
            style={{
              display: "flex",
              alignItems: "center",
              justifyContent: "space-between",
              gap: 40,
              fontFamily: "Inter, sans-serif",
            }}
          >
            {/* CTA pill */}
            <div
              style={{
                opacity: ctaIn,
                transform: `translateY(${
                  interpolate(ctaIn, [0, 1], [16, 0]) + ctaBreathe
                }px) scale(${interpolate(ctaIn, [0, 1], [0.94, 1])})`,
                display: "flex",
                alignItems: "center",
                gap: 28,
              }}
            >
              <div
                style={{
                  position: "relative",
                  padding: "32px 64px",
                  border: `3px solid ${COLORS.orange}`,
                  borderRadius: 999,
                  backgroundColor: "rgba(248,102,6,0.06)",
                  fontFamily: "Inter, sans-serif",
                  fontWeight: 600,
                  fontSize: 52,
                  color: COLORS.orange,
                  letterSpacing: "-0.005em",
                  boxShadow: `0 0 60px rgba(248,102,6,${ctaGlow * 0.35})`,
                }}
              >
                Start free → apify.com
              </div>
            </div>

            {/* Promo code line */}
            <div
              style={{
                display: "flex",
                flexDirection: "column",
                alignItems: "flex-end",
                gap: 12,
                opacity: promoIn,
                transform: `translateY(${interpolate(
                  promoIn,
                  [0, 1],
                  [12, 0],
                )}px)`,
                fontFamily: "Inter, sans-serif",
              }}
            >
              <div
                style={{
                  fontFamily: "Inter, sans-serif",
                  fontSize: 32,
                  fontWeight: 500,
                  color: COLORS.textSubtle,
                  letterSpacing: "0.12em",
                  textTransform: "uppercase",
                }}
              >
                Link in description
              </div>
              <div
                style={{
                  fontFamily: "Inter, sans-serif",
                  fontSize: 44,
                  fontWeight: 600,
                  color: COLORS.text,
                  letterSpacing: "-0.005em",
                }}
              >
                <span style={{ color: COLORS.textMuted }}>$5 credit </span>
                <span style={{ color: COLORS.orange }}>auto-applied</span>
              </div>
            </div>
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

// ============================================================
// Main Composition
// ============================================================
const MainComposition: React.FC = () => {
  return (
    <TransitionSeries>
      <TransitionSeries.Sequence durationInFrames={20}>
        <BlackScreen />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: TRANSITION })}
      />

      <TransitionSeries.Sequence durationInFrames={SCENE_ONE + TRANSITION}>
        <SceneOne />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: TRANSITION })}
      />

      <TransitionSeries.Sequence durationInFrames={SCENE_TWO + TRANSITION}>
        <SceneTwo />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: TRANSITION })}
      />

      <TransitionSeries.Sequence durationInFrames={25}>
        <BlackScreen />
      </TransitionSeries.Sequence>
    </TransitionSeries>
  );
};

export default MainComposition;
